"""rig_test: render the final report only after verified restoration and release."""
import csv,gzip,json,io,re
from pathlib import Path
from analyze_review import OUT,load,dist,write
from prepare_review import ROOT

def f(x):return f'{x:.3f}'
def quant(d):return ' / '.join(f(d[k]) for k in ['p50','p95','p99','maximum'])
def main():
    s=load(OUT/'summary.json');w=load(OUT/'windows.json');life=load(OUT/'lifecycle-evidence.json')
    provenance=load(OUT/'session-provenance.json');qa=load(OUT/'native-qa.json');b=load(OUT/'bucket-summary.json')
    release=life['r2']['lock-released.json'];restore=life['r2']['restore-receipt.json']
    assert restore['restored'] and restore['preferences_hash_matches'] and not restore['rig_running']
    assert not release['lease']['held'] and release['lease']['pending']==0
    conditions=['morning','normal','evening'];arms=['workday','before','after']
    for arm in arms:
        for c in conditions:
            g=s[arm+'-'+c];assert len(g['windows'])==3
            for label in g['windows']:
                r=next(v for v in w if v['label']==label);assert r['seconds']>=60 and r['clean']
                # Recheck portable committed tables independently of the private exports.
                for suffix,col,d in [('observations','wholeFrameMs',r['wholeFrame']),('frames','combinedUnionMs',r['modWork'])]:
                    rows=list(csv.DictReader(io.StringIO(gzip.decompress((OUT/(label+'-'+suffix+'.csv.gz')).read_bytes()).decode())))
                    actual=dist([float(v[col]) for v in rows]);assert actual['samples']==d['samples']
                    for k in ['p50','p95','p99','maximum']:assert abs(actual[k]-d[k])<.00011
    verdict='PASS' if all(s['workday-'+c]['worstWindowP95']<=5 and s['workday-'+c]['modOver50']==0 for c in conditions) else 'FAIL'
    write('delivery-checks.json',dict(role='rig_test',verdict=verdict,primaryWindows=27,allPortableQuantilesVerified=True,allPrimaryWindowsAtLeast60Seconds=True,sourceUntouched=True,restoreVerified=True,leaseReleased=True))
    labels={'morning':'Morning commute','normal':'Normal noon','evening':'Evening commute'}
    def bodies(group):
        rows=[r for r in w if r['label'] in group['windows']]
        counts=[[int(re.search(key+r'=(\d+)',r['physical']).group(1)) for r in rows] for key in ['pedestrians','cars']]
        return ' / '.join(str(min(v))+'–'+str(max(v)) for v in counts)
    lines=['# Windows performance review — 30 October 2026','',f'Role: `rig_test`. **{verdict} for the measured normal and rush-hour mod-work gate.** The implementation-plan criterion is combined Update/food-authority union **p95 ≤5 ms**, without repeated mod-attributable >50 ms stalls. Normal, morning and evening each pass in all three primary windows; none has mod work >50 ms. **This is not a 5 ms maximum guarantee**: maxima exceed 5 ms. Whole-frame stalls, unavailable allocation counters and limited City Performance activation remain explicit below. This review gives no release or ordinary-save deployment clearance.','',f"Tested SHA: `{provenance['testedSha']}`; production DLL SHA-256: `{provenance['productionDllSha256']}`. Requested fetch advanced the branch by a documentation-only commit. Verified first-session windows at `{provenance['firstSha']}` are reused: production source and rebuilt production/helper DLL hashes are identical. Build passed; offline sanity **1,551 passed / 0 failed / 0 skipped**. No production code, tests or mod behavior was changed. [Provenance](2026-10-30/session-provenance.json).",'', '**Primary dependency-only results.** Three warm ≥60-second windows per condition, Monday day 8; targets 07:00, 12:00 and 15:30 plus 15-second normal-speed warmup. Frames are whole/mod counts; quantiles are p50 / p95 / p99 / max in ms, pooled from individual frames.','', '| Condition | Seconds | Frames whole/mod | Whole-frame ms | Combined mod-work ms | Worst window mod p95 |','|---|---:|---:|---:|---:|---:|']
    for c in conditions:
        g=s['workday-'+c]
        lines.append(f"| {labels[c]} | {g['seconds']:.2f} | {g['wholeFrame']['samples']}/{g['modWork']['samples']} | {quant(g['wholeFrame'])} | {quant(g['modWork'])} | {f(g['worstWindowP95'])} |")
    def clock_time(minute):
        minute=int(minute)%1440
        return f'{minute//60:02}:{minute%60:02}'
    ranges=[]
    for c in conditions:
        rows=[r for r in w if r['label'] in s['workday-'+c]['windows']]
        ranges.append(c+' '+clock_time(min(r['times']['firstMinute'] for r in rows))+'–'+clock_time(max(r['times']['lastMinute'] for r in rows)))
    lines+=['','Actual sampled in-game spans: '+', '.join(ranges)+'. Gaps between windows contain control/export work.']
    lines+=['Endpoint pedestrian/car samples: '+', '.join(c+' '+bodies(s['workday-'+c]) for c in conditions)+'. These are sparse observations, not maxima.']
    lines+=['','| Condition | Whole >33 / >100 ms | Mod >5 / >33 / >100 ms | GC generation counts 0/1/2 | Alloc bytes/frame p50/p95; total |','|---|---:|---:|---:|---|']
    for c in conditions:
        g=s['workday-'+c];rows=[r for r in w if r['label'] in g['windows']]
        lines.append(f"| {labels[c]} | {g['wholeOver33']} / {g['wholeOver100']} | {sum(r['modOver5'] for r in rows)} / {g['modOver33']} / {g['modOver100']} | {'/'.join(map(str,g['gc']))} | Unavailable / unavailable; unavailable |")
    lines+=['','GC counts are summed raw in-window observations, excluding stop/export overhead; Mono generations can alias, so do not add columns. Per-window GC counts and signed live-heap distributions are retained in [windows.json](2026-10-30/windows.json). Neither the current-thread allocation counter nor Unity allocation recorder supplied valid bytes allocated. Heap deltas are **not allocation totals**, and subsystem allocation attribution is unavailable. GC coincidence does not identify a pause cause.','', '**Subsystems.** Inclusive p95 / max ms per frame; nested percentiles must not be added. Primary hooks cover the first five rows. Separate detail captures cover traffic-core, food and optional scheduling; these carry extra instrumentation and a different minute/body mix.','', '| Bucket | Morning | Normal noon | Evening |','|---|---:|---:|---:|']
    for name in ['PopulationRuntime.AdvancePopulation','PhysicalPopulation.Update','PhysicalVehicles.Update','CitySimulator.RefreshTrafficClosures','PhysicalTrafficHooks.FixedStepPostfix']:
        vals=[s['workday-'+c]['components'][name] for c in conditions]
        lines.append('| '+name+' | '+' | '.join(f"{f(v['p95'])} / {f(v['maximum'])}" for v in vals)+' |')
    details={c:next(r for r in b if f'workday-{c}-detail-' in r['file']) for c in conditions}
    for bucket in ['traffic-core','food-commerce','food-authority','optional-refresh']:
        vals=[details[c]['buckets'][bucket]['perObservedFrameMs'] for c in conditions]
        lines.append('| '+bucket+' (detail) | '+' | '.join(f"{f(v['p95'])} / {f(v['maximum'])}" for v in vals)+' |')
    saves=[r for r in b if 'save-stop-' in r['file']]
    savecost=max(r['buckets']['save']['totalMs'] for r in saves);serial=max(r['buckets']['serialize']['totalMs'] for r in saves)
    lines+=['',f"Two **separate** manual-save steps measured mod save/serialization **191.751/189.735 ms** and **{savecost:.3f}/{serial:.3f} ms** (one call each; no save-call p95 inference). Serialization is nested in save. These calls are not charged to gameplay windows or used as full native disk-save timings. Food-commerce per-frame p95 is zero because calls are sparse, not because food work is free. [Bucket evidence](2026-10-30/bucket-summary.json).",'', '**City Performance load-order cases.** Version 0.5.1, retained repo-build source `46585ff`, Workshop item `3825351532`; archive and DLL hashes are in [lifecycle evidence](2026-10-30/lifecycle-evidence.json). Both A-before and Z-after directory placements completed three windows per condition.','', '| Directory placement / condition | Whole p95 / max ms | Mod p95 / max ms | Δ whole p95 / mod p95 vs alone, ms |','|---|---:|---:|---:|']
    for arm in ['before','after']:
        for c in conditions:
            g=s[arm+'-'+c];base=s['workday-'+c]
            lines.append(f"| {arm} / {labels[c]} | {f(g['wholeFrame']['p95'])} / {f(g['wholeFrame']['maximum'])} | {f(g['modWork']['p95'])} / {f(g['modWork']['maximum'])} | {g['wholeFrame']['p95']-base['wholeFrame']['p95']:+.3f} / {g['modWork']['p95']-base['modWork']['p95']:+.3f} |")
    lines+=['','**Effective reverse patch order was not feasible:** City Performance initialization-load hooks precede Persistent City city-load hooks in both placements. More importantly, City Performance marks this native assembly **unverified**: behavioral optimizations stay off; timing/trace hooks and the presentation-only button-caption hook run. Four named inactive capabilities are pedestrian refill, midnight cleanup deferral, tree detail and cinematic coverage; autosave integration is also inactive. Thus these are observations of the fail-closed package with timing overhead, not evidence for active optimizations or two genuinely reversed patch orders. Shared methods are `PedestrianSpawner.SetActivePedestrians`, `TrafficManager.FixedUpdate` and `GameManager.RunMainGameTick`; both owners remain attached, with no new Persistent City exception or explicit patch-conflict error observed. This does not prove semantic compatibility of disabled patches. [Patch inventory](2026-10-30/patch-inventory.json), [chronology](2026-10-30/load-order.json), [native QA](2026-10-30/native-qa.json).','', '**Historical comparison and PR effects.** The supplied “28 Oct whole-frame 31.63/517.95” reference is actually **combined mod p95/max from the 24 October Mac final candidate**, described in [bounded implementation](../2026-10-24-bounded-implementation.md). The tracked summary gives whole-frame p95 359.1553 ms; its whole-frame maximum was not independently verified in this relaunch. The 28 October rounds are source/offline evidence.','', '| Capture | Whole p95 / max ms | Mod p95 / max ms | Comparison limit |','|---|---:|---:|---|','| 24 Oct Mac quoted reference | 359.155 / unverified | 31.629 / 517.950 | Different machine, build, workload |','| 27 Oct PC candidate Rush A | 14.032 / 81.220 | 1.904 / 45.663 | Older build; City Performance present |']
    for c in ['morning','evening']:
        g=s['workday-'+c];lines.append(f"| Current PC {c} | {f(g['wholeFrame']['p95'])} / {f(g['wholeFrame']['maximum'])} | {f(g['modWork']['p95'])} / {f(g['modWork']['maximum'])} | Unmatched historical comparison |")
    lines+=['','The current samples are below the historical mod-work values; this establishes no causal PR speedup. Today has no PR #1/#2/#3 counterfactual. Earlier [optional-stop fresh-process evidence](../rig/2026-10-29-pr3-optionB-r2/README.md) records +0.0704 ms p50 / +0.0722 ms p95 mod work at the default setting; its primary run instead showed +0.1484/+0.2722 ms. Those descriptive results and their noise limits remain distinct from today. The [27 October PC campaign](../2026-10-27-performance-pc.md) already met 5 ms p95 before these PRs.','', '**Hotspots and proposed fix order.** Gain estimates below are hypotheses, not measured changes. Halving an inclusive bucket gives the shown optimistic bucket reduction; actual whole-frame p95 improvement may be zero, and rows cannot be added. No fix was made.','', '| Priority / hotspot | Evidence, p95 / max ms | Estimated gain at p95 / max | Effort / risk |','|---|---:|---|---|']
    phys=[s['workday-'+c]['components']['PhysicalPopulation.Update'] for c in conditions];closure=[s['workday-'+c]['components']['CitySimulator.RefreshTrafficClosures'] for c in conditions]
    optional=[details[c]['buckets']['optional-refresh']['perObservedFrameMs'] for c in conditions]
    for title,vals,effort,risk in [('1. Physical population selection/body updates',phys,'M','High: body/identity continuity'),('2. Closure refresh cadence',closure,'M','High: live road closure correctness'),('3. Optional-stop refresh',optional,'M','High: stop validity and saved decisions')]:
        p95=max(v['p95'] for v in vals);mx=max(v['maximum'] for v in vals)
        lines.append(f'| {title} | {f(p95)} / {f(mx)} | 50% bucket scenario: ≤{f(p95/2)} / ≤{f(mx/2)} ms | {effort} / {risk} |')
    lines.append(f'| 4. Save serialization | One-call max {f(serial)} | Gameplay p95: 0; save max: ~{f(serial*.25)} ms if reduced 25% | L / High: immutable snapshot, schema and interrupted saves |')
    lines+=['','First narrow physical selection/body work because it dominates measured recurring cost. Then examine closure refresh while preserving live closure handling. Next profile optional refresh before optimizing its sparse ~3 ms tail. Treat save serialization separately: it has the largest observed mod call, but autosave-off gameplay gains nothing from a save-only change. Obtain a verified allocation-capable native profile before proposing GC-specific fixes.','', '**Method, noise and limits.** Same retained disposable FT morning-base fixture, production defaults (25% optional stops, 48 pedestrian/24 car caps, 120 m radius, one-third calendar pace), 957 residents, 1× in windows. RTX 4070 / i5-13600KF, Direct3D11, 1920×1080 Low, vSync off, target 90. Stationary camera; real body counts vary and caps are not saturated. The helper measures wall intervals and the historical Update/authority union; fixed-step/intersection/force hooks outside that union remain separate inclusive buckets. Results are not presented-frame FPS proof. Windows with extra hooks are excluded from primary pooling. Existing floor(n×q) quantiles and first partial whole-frame interval are retained for historical comparability; partial mod frames are excluded. Detailed event instrumentation has unquantified overhead; it was identical across placements. No capture-off overhead experiment was done.','',f"All {len(w)} retained windows have clean validity records; 27 are primary Monday windows, nine are supplemental Friday/weekend windows and four are detail captures. Friday belongs to the mod's three-day weekend and is not commute evidence. All three morning primary windows and earlier supplemental/detail/save captures were recovered from the read-only first stage; the unfinished first-session noon capture is excluded. Sequential runs, uncontrolled outside activity, changing unsaved geometry/body history and the retained versus fresh morning set limit causal comparisons. The whole-frame 10% matched-reference release gate is not established. [Method](2026-10-30/method.json), [all quantiles and environment](2026-10-30/windows.json), [raw-file hashes](2026-10-30/raw-provenance.json).",'', '**Spikes and native QA.** Dependency-only evening contains four >100 ms wall intervals (104.010–174.875 ms), with no coincident GC increments and neighboring mod union <0.8 ms; cause remains unresolved. Other spikes and GC coincidences across all cases are retained with neighboring frame/event/component context; coincidence is not causal attribution. No measured mod >50 ms occurs in the primary campaign. No new Persistent City exception was found. Native building-hover null-reference errors and a diagnostic shutdown null-reference in `PlayerHelper.SaveCurrentPosition` are retained; the latter occurs when restoring autosave flushes a pending native midnight save, outside timing. [Spike evidence](2026-10-30/spikes-and-gc.json), [QA stacks](2026-10-30/native-qa.json).','', '**Autosave and restoration.** Original autosave was enabled (`preventAutoSave=false`, five-minute interval, three slots). It was disabled again after loading and verified off before/after every window; no save was in progress, save inventories were unchanged and no actual save-start/completion markers appeared. Manual saves were outside timing. [Per-window proofs](2026-10-30/autosave-validity.json).','',f"Both sessions restored and hash-verified **{restore['profile_files_verified']} profile files and {restore['receipt_references_verified']} installation references**, original ModsLocal/config, root files and exact preference export. Original autosave is restored by those profile/registry hashes; the restored game was not relaunched. Added A/Z City Performance placements and diagnostic helpers were removed; the rig's preexisting CityPerformance folder was preserved and restored. Only the verified agent1 process was stopped. Lease released, held=false, pending=0; no takeover. [Backup, restore and release receipts](2026-10-30/lifecycle-evidence.json), [original settings](2026-10-30/original-settings.json), [portable export checks](2026-10-30/delivery-checks.json). Full private backups, native logs, DLLs and raw saves remain outside Git. No normal profile, Steam, Workshop or RLO source was changed.",'']
    report=OUT.parent/'2026-10-30-performance-review.md'
    report.write_text('\n'.join(lines),encoding='utf-8')
    # The requested cross-project log directory is explicit, independent of worktree nesting.
    dest=Path.home()/'Coding_Projects/.agent-logs/persistent-city-perf-review-2026-10-30.md'
    dest.parent.mkdir(exist_ok=True,parents=True);dest.write_bytes(report.read_bytes())
    print('Report written; verdict',verdict,'words',len(report.read_text().split()))

if __name__=='__main__':main()
